package com.archos.mediacenter.video.player;

import android.content.Context;
import android.graphics.Color;
import android.view.Gravity;
import android.widget.*;
import androidx.preference.PreferenceManager;
import com.archos.mediacenter.video.leanback.cinema.*;
import static com.archos.mediacenter.video.leanback.cinema.CinemaUi.*;

/** Native remote-first appearance panel; all changes update the existing subtitle renderer. */
final class CinemaSubtitleAppearance {
    static void show(Context context,SubtitleManager manager,AdaptiveSubtitleContrast contrast,android.view.View reference){
        int width=reference!=null&&reference.getWidth()>0?reference.getWidth():dp(context,264),height=reference!=null&&reference.getHeight()>0?reference.getHeight():dp(context,440);
        LinearLayout column=new LinearLayout(context);column.setOrientation(LinearLayout.VERTICAL);column.setPadding(dp(context,12),dp(context,4),dp(context,12),dp(context,4));
        Runnable[] refresh={null};
        TextView preview=text(context,16,true);preview.setText(label(context,"معاينة اللون","Color preview"));preview.setGravity(Gravity.CENTER);preview.setPadding(dp(context,12),dp(context,8),dp(context,12),dp(context,8));column.addView(preview);
        TextView auto=control(context,column,"",()->{});TextView note=text(context,12,false);note.setText(label(context,"يختار الأبيض أو الأسود حسب خلفية منطقة الترجمة. للترجمات النصية فقط.","Chooses white or black from the video behind the text. Text subtitles only."));note.setPadding(0,dp(context,4),0,dp(context,4));column.addView(note);
        LinearLayout colors=new LinearLayout(context);colors.setOrientation(LinearLayout.VERTICAL);column.addView(colors);String[] labels={"White","Yellow","Black","More colors"};int[] values={Color.WHITE,Color.YELLOW,Color.BLACK};
        TextView size=text(context,14,true);size.setPadding(0,dp(context,4),0,dp(context,4));
        LinearLayout sizing=new LinearLayout(context);sizing.setGravity(Gravity.CENTER_VERTICAL);column.addView(sizing);sizing.addView(size,new LinearLayout.LayoutParams(0,-2,1));TextView minus=control(context,sizing,"−",()->{manager.setSize(Math.max(10,manager.getSize()-2));save(context,manager);if(refresh[0]!=null)refresh[0].run();});TextView plus=control(context,sizing,"+",()->{manager.setSize(Math.min(100,manager.getSize()+2));save(context,manager);if(refresh[0]!=null)refresh[0].run();});
        TextView position=text(context,14,true);position.setPadding(0,dp(context,4),0,dp(context,4));LinearLayout positioning=new LinearLayout(context);positioning.setGravity(Gravity.CENTER_VERTICAL);column.addView(positioning);positioning.addView(position,new LinearLayout.LayoutParams(0,-2,1));TextView down=control(context,positioning,"↓",()->{manager.setVerticalPosition(Math.max(0,manager.getVerticalPosition()-5));save(context,manager);if(refresh[0]!=null)refresh[0].run();});TextView up=control(context,positioning,"↑",()->{manager.setVerticalPosition(Math.min(255,manager.getVerticalPosition()+5));save(context,manager);if(refresh[0]!=null)refresh[0].run();});
        TextView outline=control(context,column,"",()->{});
        Runnable update=()->{boolean enabled=contrast.enabled();auto.setText(label(context,"لون تلقائي: ","Automatic contrast: ")+(enabled?"On":"Off"));int foreground=contrast.color();preview.setTextColor(foreground);preview.setBackground(rounded(androidx.core.graphics.ColorUtils.calculateLuminance(foreground)>0.5?0xff171717:0xfff5f5f5,dp(context,8),0));size.setText("Size · "+manager.getSize());position.setText("Position · "+manager.getVerticalPosition());outline.setEnabled(!enabled);outline.setText("Outline · "+(enabled?"On (automatic)":manager.getOutlineState()?"On":"Off"));};
        auto.setOnClickListener(v->{contrast.setEnabled(!contrast.enabled());update.run();});outline.setOnClickListener(v->{if(contrast.enabled())return;manager.setOutlineState(!manager.getOutlineState());save(context,manager);update.run();});
        LinearLayout colorRow=null;
        for(int n=0;n<labels.length;n++){if(n%2==0){colorRow=new LinearLayout(context);colors.addView(colorRow);}final int index=n;TextView preset=control(context,colorRow,labels[n],()->{if(index<values.length){contrast.setEnabled(false);manager.setColor(values[index]);save(context,manager);update.run();}else{showPalette(context,manager,contrast,width,height,update);}});LinearLayout.LayoutParams cell=(LinearLayout.LayoutParams)preset.getLayoutParams();cell.width=0;cell.weight=1;preset.setLayoutParams(cell);}
        minus.setContentDescription("Decrease subtitle size");plus.setContentDescription("Increase subtitle size");down.setContentDescription("Lower subtitles");up.setContentDescription("Raise subtitles");
        refresh[0]=update;
        androidx.appcompat.app.AlertDialog dialog=panel(context,label(context,"مظهر الترجمة","Subtitle appearance"),column,width,height);dialog.setOnDismissListener(d->{contrast.listener(null);manager.fadeSubtitlePositionHint(false);save(context,manager);});contrast.listener(update);update.run();auto.requestFocus();
    }
    private static androidx.appcompat.app.AlertDialog panel(Context context,String title,android.view.View body,int width,int height){
        LinearLayout shell=new LinearLayout(context);shell.setOrientation(LinearLayout.VERTICAL);shell.setMinimumHeight(height);shell.setPadding(0,0,0,dp(context,4));
        TextView heading=text(context,18,true);heading.setText(title);heading.setGravity(Gravity.CENTER);heading.setPadding(dp(context,10),dp(context,10),dp(context,10),dp(context,8));shell.addView(heading,new LinearLayout.LayoutParams(-1,-2));
        ScrollView scroll=new ScrollView(context);scroll.setFillViewport(false);scroll.addView(body);shell.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        androidx.appcompat.app.AlertDialog dialog=CinemaUi.dialog(context).create();TextView done=control(context,shell,"Done",dialog::dismiss);LinearLayout.LayoutParams footer=(LinearLayout.LayoutParams)done.getLayoutParams();footer.width=-1;footer.leftMargin=dp(context,12);footer.rightMargin=dp(context,12);footer.bottomMargin=dp(context,8);done.setLayoutParams(footer);
        dialog.setView(shell,0,0,0,0);dialog.show();if(dialog.getWindow()!=null){dialog.getWindow().setBackgroundDrawable(rounded(CinemaTokens.PLAYER_PANEL,dp(context,12),0));dialog.getWindow().getDecorView().setPadding(0,0,0,0);dialog.getWindow().setGravity(Gravity.CENTER);dialog.getWindow().setLayout(Math.min(width,context.getResources().getDisplayMetrics().widthPixels-dp(context,24)),Math.min(height,context.getResources().getDisplayMetrics().heightPixels-dp(context,24)));}return dialog;
    }
    private static void showPalette(Context context,SubtitleManager manager,AdaptiveSubtitleContrast contrast,int width,int height,Runnable update){
        LinearLayout grid=new LinearLayout(context);grid.setOrientation(LinearLayout.VERTICAL);grid.setPadding(dp(context,12),dp(context,8),dp(context,12),dp(context,8));String[] colors=context.getResources().getStringArray(com.archos.mediacenter.video.R.array.color_picker_subtitle);LinearLayout row=null;android.view.View first=null;
        for(int n=0;n<colors.length;n++){if(n%4==0){row=new LinearLayout(context);grid.addView(row);}int value=Color.parseColor(colors[n]);android.view.View cell=new android.view.View(context);cell.setFocusable(true);cell.setClickable(true);cell.setContentDescription("Color "+colors[n]);cell.setBackground(rounded(value,dp(context,6),0));LinearLayout.LayoutParams size=new LinearLayout.LayoutParams(0,Math.max(dp(context,32),(width-dp(context,48))/4),1);size.setMargins(dp(context,3),dp(context,3),dp(context,3),dp(context,3));row.addView(cell,size);if(first==null)first=cell;cell.setOnFocusChangeListener((v,focused)->cell.setForeground(focused?rounded(Color.TRANSPARENT,dp(context,6),CinemaTokens.FOCUS):null));cell.setOnClickListener(v->{contrast.setEnabled(false);manager.setColor(value);save(context,manager);update.run();});}
        panel(context,"Subtitle color",grid,width,height);if(first!=null)first.requestFocus();
    }
    private static TextView control(Context c,LinearLayout parent,String label,Runnable action){TextView button=text(c,14,true);button.setText(label);button.setGravity(Gravity.CENTER);button.setMinimumWidth(dp(c,32));button.setPadding(dp(c,8),dp(c,6),dp(c,8),dp(c,6));focusable(button);android.graphics.drawable.StateListDrawable background=new android.graphics.drawable.StateListDrawable();background.addState(new int[]{android.R.attr.state_focused},rounded(CinemaTokens.FOCUS,dp(c,6),0));background.addState(new int[]{android.R.attr.state_pressed},rounded(CinemaTokens.PRESSED,dp(c,6),0));background.addState(new int[]{},rounded(CinemaTokens.SURFACE,dp(c,6),0));button.setBackground(background);button.setMinimumHeight(dp(c,32));LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(parent.getOrientation()==LinearLayout.VERTICAL?-1:-2,-2);params.rightMargin=dp(c,4);params.topMargin=dp(c,4);parent.addView(button,params);button.setOnClickListener(v->action.run());return button;}
    private static void save(Context c,SubtitleManager manager){PreferenceManager.getDefaultSharedPreferences(c).edit().putInt(PlayerActivity.KEY_SUBTITLE_SIZE,manager.getSize()).putInt(PlayerActivity.KEY_SUBTITLE_VPOS,manager.getVerticalPosition()).putInt(PlayerActivity.KEY_SUBTITLE_COLOR,manager.getColor()).putBoolean(PlayerActivity.KEY_SUBTITLE_OUTLINE,manager.getOutlineState()).apply();}
}
